import test from'node:test';import assert from'node:assert/strict';import{make,validate,apply,markdown}from'./state.js';import{portable,parse}from'../creative-kit/state.js';
test('forks keep independent wording and immutable source snapshots',()=>{const w=make();const before=w.nodes[0].mechanism;apply(w,{type:'fork',id:'n3',parent:'n1'});apply(w,{type:'edit',item:'n1',field:'mechanism',value:'A later change'});assert.equal(w.nodes[2].mechanism,before);assert.equal(w.nodes[2].sources[0].mechanism,before);assert.throws(()=>apply(w,{type:'remove',id:'n1'}));});
test('combining records both ancestors and never silently merges their mechanisms',()=>{const w=make();apply(w,{type:'combine',id:'n3'});assert.deepEqual(w.nodes[2].parents,['n1','n2']);assert.equal(w.nodes[2].mechanism,'');assert.equal(w.nodes[2].sources.length,2);validate(w);});
test('comparison displaces duplicates and portable graph rejects cycles or missing parents',()=>{const w=make();apply(w,{type:'compare',id:'n2',slot:0});assert.deepEqual(w.compare,['n2',null]);assert.deepEqual(parse(portable(w,'family',validate),'family',validate),w);assert.ok(markdown(w).includes('Source snapshot'));w.nodes[0].parents=['n2'];assert.throws(()=>validate(w));});
